-- Actual enrichment inputs have independent monotonic versions. Generated
-- summaries and question metadata do not change these input versions.
CREATE TABLE knowledge_enrichment_row_versions (
 row_kind TEXT NOT NULL CHECK(row_kind IN ('knowledge','chunk','model','routing','tenant')),
 row_id TEXT NOT NULL CHECK(length(trim(row_id)) > 0),
 revision BIGINT NOT NULL CHECK(revision > 0), PRIMARY KEY(row_kind,row_id)
);
CREATE TABLE knowledge_producer_inputs (
 id TEXT PRIMARY KEY CHECK(length(trim(id)) > 0),
 admission_id TEXT NOT NULL REFERENCES knowledge_input_admissions(admission_id),
 purpose TEXT NOT NULL CHECK(purpose IN ('summary','question','image')),
 input_digest TEXT NOT NULL CHECK(length(input_digest) = 64),
 original_proof TEXT NOT NULL,
 actor_selector TEXT NOT NULL,
 model_digest TEXT NOT NULL CHECK(length(model_digest) = 64)
);
CREATE TRIGGER knowledge_producer_input_immutable_update BEFORE UPDATE ON knowledge_producer_inputs BEGIN SELECT RAISE(ABORT,'immutable actual producer input'); END;
CREATE TRIGGER knowledge_producer_input_immutable_delete BEFORE DELETE ON knowledge_producer_inputs BEGIN SELECT RAISE(ABORT,'immutable actual producer input'); END;
INSERT INTO knowledge_enrichment_row_versions(row_kind,row_id,revision) SELECT 'knowledge',id,1 FROM knowledges;
CREATE TRIGGER knowledge_enrichment_knowledge_insert AFTER INSERT ON knowledges BEGIN INSERT INTO knowledge_enrichment_row_versions(row_kind,row_id,revision) VALUES('knowledge',NEW.id,1) ON CONFLICT(row_kind,row_id) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER knowledge_enrichment_knowledge_update AFTER UPDATE ON knowledges WHEN OLD.tenant_id IS NOT NEW.tenant_id OR OLD.knowledge_base_id IS NOT NEW.knowledge_base_id OR OLD.type IS NOT NEW.type OR OLD.title IS NOT NEW.title OR OLD.source IS NOT NEW.source OR OLD.channel IS NOT NEW.channel OR OLD.file_name IS NOT NEW.file_name OR OLD.folder_path IS NOT NEW.folder_path OR OLD.file_type IS NOT NEW.file_type OR OLD.file_hash IS NOT NEW.file_hash OR OLD.file_path IS NOT NEW.file_path OR OLD.custom_metadata IS NOT NEW.custom_metadata OR OLD.deleted_at IS NOT NEW.deleted_at OR (CASE WHEN OLD.channel = 'nextcloud' AND NEW.channel = 'nextcloud' AND json_valid(OLD.metadata) AND json_valid(NEW.metadata) THEN json_remove(OLD.metadata,'$.nextcloud_etag') IS NOT json_remove(NEW.metadata,'$.nextcloud_etag') ELSE OLD.metadata IS NOT NEW.metadata END) BEGIN INSERT INTO knowledge_enrichment_row_versions(row_kind,row_id,revision) VALUES('knowledge',NEW.id,1) ON CONFLICT(row_kind,row_id) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER knowledge_enrichment_knowledge_delete AFTER DELETE ON knowledges BEGIN INSERT INTO knowledge_enrichment_row_versions(row_kind,row_id,revision) VALUES('knowledge',OLD.id,1) ON CONFLICT(row_kind,row_id) DO UPDATE SET revision=revision+1; END;
