CREATE TRIGGER knowledge_enrichment_chunk_delete AFTER DELETE ON chunks BEGIN INSERT INTO knowledge_enrichment_row_versions(row_kind,row_id,revision) VALUES('chunk',OLD.id,1) ON CONFLICT(row_kind,row_id) DO UPDATE SET revision=revision+1; END;
